"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11379"],{74325(e){e.exports=JSON.parse('{"id":"FIN-1359","slug":"net-working-capital-peg","term":"Net Working Capital Peg","also_known_as":[],"difficulty":"Advanced","definition":"A net working capital peg is a target level of working capital agreed between a buyer and seller in an acquisition, against which the actual working capital at completion is compared to adjust the purchase price.","explanation":["A business needs a normal level of working capital, such as receivables and inventory minus payables, to operate. Buyers expect to receive this level as part of the business. Without a peg, a seller could, for example, collect receivables early or delay paying suppliers before completion, taking cash out of the business.","The peg is usually set based on the business\'s average working capital over a recent period, often twelve months, adjusted for seasonality and unusual items.","For example, the parties agree a peg of 10,000,000. At completion, the actual working capital is 9,200,000. The purchase price is reduced by 800,000. If working capital had been 10,500,000, the price would have increased by 500,000.","Negotiating the peg can be contentious, because small differences in definitions or the period used can significantly affect the price. It is closely linked to completion accounts and debt-free cash-free pricing."],"note":"","total":1725,"prev":{"slug":"net-working-capital","term":"Net Working Capital"},"next":{"slug":"net-worth","term":"Net Worth"}}')}}]);